/*
# Seed Cities and Recipes Data

Populates recipes_city (10 cities) and recipes_recipe (32 recipes) with
Pakistani recipe data from the Ingrido seed JSON files.
*/

-- CITIES
ON CONFLICT (name) DO NOTHING;

-- RECIPES (using a DO block to map city_name -> city_id)
DO $$
DECLARE
  c_lahore bigint := (SELECT id FROM recipes_city WHERE name='Lahore');
  c_karachi bigint := (SELECT id FROM recipes_city WHERE name='Karachi');
  c_islamabad bigint := (SELECT id FROM recipes_city WHERE name='Islamabad');
  c_peshawar bigint := (SELECT id FROM recipes_city WHERE name='Peshawar');
  c_multan bigint := (SELECT id FROM recipes_city WHERE name='Multan');
  c_quetta bigint := (SELECT id FROM recipes_city WHERE name='Quetta');
  c_faisalabad bigint := (SELECT id FROM recipes_city WHERE name='Faisalabad');
  c_rawalpindi bigint := (SELECT id FROM recipes_city WHERE name='Rawalpindi');
  c_sialkot bigint := (SELECT id FROM recipes_city WHERE name='Sialkot');
  c_hyderabad bigint := (SELECT id FROM recipes_city WHERE name='Hyderabad');
BEGIN
  -- Lahore
  ON CONFLICT DO NOTHING;

  -- Karachi
  ON CONFLICT DO NOTHING;

  -- Islamabad
  ON CONFLICT DO NOTHING;

  -- Peshawar
  ON CONFLICT DO NOTHING;

  -- Multan
  ON CONFLICT DO NOTHING;

  -- Quetta
  ON CONFLICT DO NOTHING;

  -- Faisalabad
  ON CONFLICT DO NOTHING;

  -- Rawalpindi
  ON CONFLICT DO NOTHING;

  -- Sialkot
  ON CONFLICT DO NOTHING;

  -- Hyderabad
  ON CONFLICT DO NOTHING;
END $$;