INSERT INTO recipes_city (name, region, tagline, latitude, longitude, is_pandamart_available, image, famous_dishes)
VALUES
('Lahore','Punjab','The Cultural Heart of Pakistan - Food Capital',31.5497,74.3436,true,'/city_images/lahore.jpeg','["Chargha","Gol Gappay","Butt Karahi","Falooda","Fried Fish"]'::jsonb),
