('Islamabad','Capital Territory','The Beautiful Capital - Modern Cuisine Hub',33.6844,73.0479,true,'/city_images/islamabad.jpeg','["Chicken Tikka","Shawarma","Trout Fish"]'::jsonb),
('Peshawar','Khyber Pakhtunkhwa','City of Flowers - Land of Traditional BBQ',34.0151,71.5249,false,'/city_images/peshawar.jpeg','["Chapli Kebab","Namak Mandi Karahi","Mutton Korma","Lamb Sajji"]'::jsonb),
('Multan','Punjab','City of Saints - Sweet Delights Paradise',30.1575,71.5249,false,'/city_images/multan.jpeg','["Multani Sohan Halwa","Mango Kulfi","Channa Chaat","Pati Gali Biryani","Sajji"]'::jsonb),
